{
  "name": "opencode-advisors-v2",
  "version": "0.1.0",
  "private": true,
  "license": "MIT",
  "type": "module",
  "description": "OpenCode v2 plugin: passive reviewer advisors that watch completed model steps and emit concise nit/concern/blocker notes",
  "repository": { "type": "git", "url": "git+https://github.com/0x4nur4g/opencode-advisors-v2.git" },
  "homepage": "https://github.com/0x4nur4g/opencode-advisors-v2#readme",
  "bugs": { "url": "https://github.com/0x4nur4g/opencode-advisors-v2/issues" },
  "keywords": ["opencode", "opencode-plugin", "opencode-v2", "advisors", "code-review", "llm"],
  "exports": {
    ".": "./index.ts"
  },
  "devDependencies": {
    "@types/bun": "^1.3.14",
    "@types/node": "^22.0.0",
    "typescript": "^5.7.0",
    "yaml": "^2.9.0"
  },
  "scripts": {
    "bundle": "bun build src/index.ts --outdir dist --target node --format esm",
    "typecheck": "tsc --noEmit",
    "test": "bun test"
  }
}
